#!/usr/bin/env python3
"""Patches the files generated by `flutter create` with LunaNest's native config.

Idempotent. Runs from the project root (see tool/bootstrap.sh).
Android: permissions, audio_service service/receiver, AudioServiceActivity.
iOS: UIBackgroundModes=audio, display name, Podfile platform.
"""
import glob
import json
import os
import re
import shutil
import sys


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


def patch_android_manifest():
    p = "android/app/src/main/AndroidManifest.xml"
    s = read(p)
    if "com.ryanheise.audioservice.AudioService" in s:
        print("AndroidManifest already patched")
        return
    if "xmlns:tools" not in s:
        s = s.replace('<manifest xmlns:android="http://schemas.android.com/apk/res/android"',
                      '<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n    xmlns:tools="http://schemas.android.com/tools"', 1)
    perms = """    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.WAKE_LOCK"/>
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE"/>
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK"/>
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
"""
    s = s.replace("<application", perms + "    <application", 1)
    s = re.sub(r'android:label="[^"]*"', 'android:label="LunaNest"', s, count=1)
    comps = """        <service android:name="com.ryanheise.audioservice.AudioService"
            android:foregroundServiceType="mediaPlayback"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.media.browse.MediaBrowserService"/>
            </intent-filter>
        </service>
        <receiver android:name="com.ryanheise.audioservice.MediaButtonReceiver"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.intent.action.MEDIA_BUTTON"/>
            </intent-filter>
        </receiver>
"""
    s = s.replace("</application>", comps + "    </application>", 1)
    write(p, s)
    print("Patched AndroidManifest.xml")


def patch_main_activity():
    files = glob.glob("android/app/src/main/kotlin/**/MainActivity.kt", recursive=True)
    if not files:
        files = glob.glob("android/app/src/main/java/**/MainActivity.java", recursive=True)
        if files:
            print("Java MainActivity found; please convert to Kotlin AudioServiceActivity manually", file=sys.stderr)
            sys.exit(1)
        print("MainActivity not found", file=sys.stderr)
        sys.exit(1)
    p = files[0]
    s = read(p)
    pkg = re.search(r"^package\s+([\w.]+)", s, re.M).group(1)
    write(p, f"package {pkg}\n\nimport com.ryanheise.audioservice.AudioServiceActivity\n\nclass MainActivity : AudioServiceActivity()\n")
    print("Patched", p)


def patch_info_plist():
    p = "ios/Runner/Info.plist"
    s = read(p)
    if "UIBackgroundModes" not in s:
        s = s.replace("</dict>\n</plist>", "\t<key>UIBackgroundModes</key>\n\t<array>\n\t\t<string>audio</string>\n\t</array>\n</dict>\n</plist>", 1)
    s = re.sub(r"(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)", r"\1LunaNest\2", s, count=1)
    write(p, s)
    print("Patched Info.plist")


def patch_podfile():
    p = "ios/Podfile"
    if not os.path.exists(p):
        return
    s = read(p)
    s2 = re.sub(r"^#?\s*platform :ios, '[\d.]+'", "platform :ios, '13.0'", s, count=1, flags=re.M)
    if s2 != s:
        write(p, s2)
        print("Patched Podfile platform")


def apply_android_branding():
    """Adaptive launcher icon (+monochrome), legacy icons and the notification icon."""
    src = "tool/branding/android/res"
    dst = "android/app/src/main/res"
    if not os.path.isdir(src):
        print("WARNING: tool/branding/android/res missing; launcher icon not replaced", file=sys.stderr)
        return
    shutil.copytree(src, dst, dirs_exist_ok=True)
    print("Applied Android launcher + notification icons")


def apply_ios_icons():
    d = "ios/Runner/Assets.xcassets/AppIcon.appiconset"
    cj = os.path.join(d, "Contents.json")
    if not os.path.exists(cj):
        print("WARNING: iOS AppIcon set not found", file=sys.stderr)
        return
    data = json.load(open(cj))
    for img in data.get("images", []):
        name = img.get("filename")
        if not name:
            continue
        px = round(float(img["size"].split("x")[0]) * int(img["scale"].rstrip("x")))
        src = f"tool/branding/ios/ios_{px}.png"
        if os.path.exists(src):
            shutil.copyfile(src, os.path.join(d, name))
        else:
            print(f"WARNING: no icon source for {px}px ({name})", file=sys.stderr)
    print("Applied iOS app icons")


if __name__ == "__main__":
    if os.path.isdir("android"):
        patch_android_manifest()
        patch_main_activity()
        apply_android_branding()
    if os.path.isdir("ios"):
        patch_info_plist()
        patch_podfile()
        apply_ios_icons()
